<div class="section-heading"><div><div class="eyebrow">Catálogo</div><h1>Serviços</h1></div><?php if(\App\Core\Authorization::allows('services.create')):?><a class="btn btn-primary" href="/services/create">+ Novo serviço</a><?php endif;?></div><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Serviço</th><th>Duração</th><th>Preço</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($services as $s):?><tr><td><strong><?=htmlspecialchars($s['name'],ENT_QUOTES,'UTF-8')?></strong><div class="small text-secondary"><?=htmlspecialchars($s['description']??'',ENT_QUOTES,'UTF-8')?></div></td><td><?=(int)$s['duration_minutes']?> min</td><td>R$ <?=number_format((float)$s['price'],2,',','.')?></td><td><span class="badge text-bg-<?=$s['active']?'success':'secondary'?>"><?=$s['active']?'Ativo':'Inativo'?></span></td><td class="text-end"><?php if(\App\Core\Authorization::allows('services.edit')):?><a class="btn btn-sm btn-outline-primary" href="/services/<?=(int)$s['id']?>/edit">Editar</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$services):?><tr><td colspan="5" class="text-center py-5 text-secondary">Nenhum serviço cadastrado.</td></tr><?php endif;?></tbody></table></div></div>
